 if not name.startswith('hbc_sha1_') and name!='hbc_hmac_sha1_digest':s=re.sub(r'(?<![A-Za-z0-9_.])'+re.escape(name)+r'(?![A-Za-z0-9_.$])','hrsha1_local_'+name,s)
